import { Component, h, Prop, ComponentInterface, Host, Element, Event, EventEmitter } from '@stencil/core';
import classnames from 'classnames';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { LinkSize, LinkTarget, LinkColorShortcut, LinkVariant } from './types';

const prefix = 'link';

/**
 * @slot default - Link text or custom content rendered inside the link.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-link',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsLink implements ComponentInterface {
  @Element() el!: HTMLKsLinkElement;

  /** Indicates whether the link is disabled. When `true`, the link will not be clickable. */
  @Prop() disabled = false;
  /** The size of the link component. Options include `inherit` to follow surrounding typography, `sm` for small, and `md` for medium. */
  @Prop() size: LinkSize = 'inherit';
  /** The visual color of the link. Can be one of the following values: `"primary"`, `"support"`, `"neutral"`、`"neutralHigh"`, `"success"`, `"warning"`, `"error"` or `"info"` */
  @Prop() color: LinkColorShortcut = 'primary';
  /**
   * @private @deprecated Use `variant` instead. The variant of link. Options include 'solid' for solid links and 'dotted' for dotted links. */
  @Prop() type?: LinkVariant;
  /** The variant of link. Options include 'solid' for solid links and 'dotted' for dotted links. */
  @Prop() variant: LinkVariant = 'solid';
  /** The URL of the linked document. This is where the link points to. */
  @Prop() href?: string;
  /** Specifies where to open the linked document. Can be one of the following values: `_self`, `_blank`, `_parent`, `_top`, or `framename`. This property is effective only when `href` is also provided. */
  @Prop() target: LinkTarget = '_self';
  /** The `download` attribute for the `<a>` tag, specifies that the target will be downloaded when a user clicks on the hyperlink. */
  @Prop() download?: string | boolean;
  /** The `hreflang` attribute for the `<a>` tag, specifies the language of the linked document. */
  @Prop() hreflang?: string;
  /** The `ping` attribute for the `<a>` tag, specifies a space-separated list of URLs to which, when the hyperlink is followed, POST requests with the body PING will be sent by the browser. */
  @Prop() ping?: string;
  /** The `referrerpolicy` attribute for the `<a>` tag, specifies which referrer information to send when following the link. */
  @Prop() referrerpolicy?: ReferrerPolicy;
  /** The `title` attribute for the `<a>` tag, specifies extra information about the link. */
  @Prop() title = '';
  /** The `rel` attribute passed to the `<a>` tag, commonly used to set security parameters like `noreferrer`. */
  @Prop() rel?: string;
  /**  Emitted when the link is clicked. `disabled` will prevent the click event. */
  @Event({ bubbles: false, composed: false }) ksClick?: EventEmitter<MouseEvent>;

  private handleClick = (event: MouseEvent) => {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
      event.stopPropagation();
      return;
    }

    if (typeof this.href === 'string') {
      sendActionTracking<HTMLKsLinkElement>(this.el, {
        eventType: 'link',
        componentParams: { href: this.href },
      });
    } else {
      sendActionTracking<HTMLKsLinkElement>(this.el, {
        eventType: 'click',
        componentParams: { text: this.el.textContent },
      });
    }

    this.ksClick?.emit(event);
  };

  constructor() {
    registerPluginManager(this.el);
  }

  render() {
    const cls = classnames(prefix, `${prefix}--${this.color}`, `${prefix}--${this.type || this.variant}`, {
      [`${prefix}--disabled`]: this.disabled,
    });
    return (
      <Host class={`KsLink KsLink--${this.size}`} role="link" aria-disabled={this.disabled ? 'true' : null}>
        <a
          class={cls}
          target={this.href && this.target}
          href={this.disabled ? undefined : this.href}
          part="base"
          aria-disabled={!!this.disabled}
          {...(this.rel ? { rel: this.target === '_blank' && !this.rel ? 'noopener noreferrer' : this.rel } : {})}
          {...(this.download ? { download: this.download } : {})}
          {...(this.hreflang ? { hreflang: this.hreflang } : {})}
          {...(this.ping ? { ping: this.ping } : {})}
          {...(this.referrerpolicy ? { referrerPolicy: this.referrerpolicy } : {})}
          {...(this.title ? { title: this.title } : {})}
          onClick={this.handleClick}
          data-testid="ks-link-index-nsmWAN"
        >
          <slot></slot>
        </a>
      </Host>
    );
  }
}
